import { test, expect } from '@playwright/test';

test.describe('Sticky Header Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    // Wait for the header to be visible
    await page.getByRole('banner').waitFor({ state: 'visible' });
  });

  test('should keep header visible when scrolling down the page', async ({ page }) => {
    // Get the header element
    const header = page.getByRole('banner');

    // Get initial header position
    const headerBox = await header.boundingBox();
    const initialTop = headerBox?.y ?? 0;

    // Scroll down the page
    await page.evaluate(() => window.scrollBy(0, 500));

    // Wait a moment for scroll to complete
    await page.waitForTimeout(300);

    // Get header position after scroll
    const headerBoxAfterScroll = await header.boundingBox();
    const topAfterScroll = headerBoxAfterScroll?.y ?? 0;

    // Header should remain at or near the top (sticky positioning)
    expect(topAfterScroll).toBeLessThanOrEqual(initialTop + 50);
  });

  test('should maintain header visibility while scrolling through content', async ({ page }) => {
    const header = page.getByRole('banner');

    // Verify header is visible before scrolling
    await expect(header).toBeVisible();

    // Scroll to middle of page
    await page.evaluate(() => window.scrollBy(0, 300));
    await page.waitForTimeout(200);

    // Header should still be visible
    await expect(header).toBeVisible();

    // Continue scrolling
    await page.evaluate(() => window.scrollBy(0, 400));
    await page.waitForTimeout(200);

    // Header should still be visible
    await expect(header).toBeVisible();
  });

  test('should have header with proper z-index layering', async ({ page }) => {
    const header = page.getByRole('banner');

    // Get the computed z-index of the header
    const zIndex = await header.evaluate((element) => {
      return window.getComputedStyle(element).zIndex;
    });

    // Z-index should be set to a high value for sticky positioning
    expect(parseInt(zIndex)).toBeGreaterThan(0);
  });

  test('should keep navigation links accessible in sticky header', async ({ page }) => {
    const header = page.getByRole('banner');

    // Scroll down to ensure header is sticky
    await page.evaluate(() => window.scrollBy(0, 600));
    await page.waitForTimeout(300);

    // Find navigation links in the header
    const navLinks = header.getByRole('link');

    // Verify at least one navigation link exists and is visible
    const linkCount = await navLinks.count();
    expect(linkCount).toBeGreaterThan(0);

    // Verify the first link is visible and clickable
    const firstLink = navLinks.first();
    await expect(firstLink).toBeVisible();
    await expect(firstLink).toBeEnabled();
  });

  test('should maintain header position during rapid scrolling', async ({ page }) => {
    const header = page.getByRole('banner');
    const headerBox = await header.boundingBox();
    const initialTop = headerBox?.y ?? 0;

    // Perform rapid scrolling
    for (let i = 0; i < 5; i++) {
      await page.evaluate(() => window.scrollBy(0, 200));
      await page.waitForTimeout(100);
    }

    // Get final header position
    const finalHeaderBox = await header.boundingBox();
    const finalTop = finalHeaderBox?.y ?? 0;

    // Header should remain in sticky position
    expect(Math.abs(finalTop - initialTop)).toBeLessThan(100);

    // Header should still be visible
    await expect(header).toBeVisible();
  });

  test('should have proper contrast and readability in sticky header', async ({ page }) => {
    const header = page.getByRole('banner');

    // Verify header has sufficient height for content
    const headerBox = await header.boundingBox();
    expect(headerBox?.height).toBeGreaterThanOrEqual(50);

    // Verify header contains readable content
    const headerText = await header.textContent();
    expect(headerText?.length).toBeGreaterThan(0);
  });

  test('should scroll back to top and header should remain visible', async ({ page }) => {
    const header = page.getByRole('banner');

    // Scroll down significantly
    await page.evaluate(() => window.scrollBy(0, 1000));
    await page.waitForTimeout(300);

    // Verify header is still visible
    await expect(header).toBeVisible();

    // Scroll back to top
    await page.evaluate(() => window.scrollTo(0, 0));
    await page.waitForTimeout(300);

    // Header should still be visible at the top
    await expect(header).toBeVisible();
    const headerBox = await header.boundingBox();
    expect(headerBox?.y).toBeLessThanOrEqual(10);
  });
});
